{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C33"],
      "claim": "Rilzabrutinib, the closest structural analogue sharing the same pyrazolopyrimidine, phenoxyphenyl, and piperidine core, had an absolute oral bioavailability of only 4.73% in humans after a single oral tablet dose compared with IV, well below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "An independent human microtracer study confirmed rilzabrutinib absolute bioavailability as <5%, reinforcing that this close analogue is clearly low-bioavailable.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C49"],
      "claim": "Acalabrutinib, a less similar BTK inhibitor with a different warhead and core, showed an absolute bioavailability of 25.3%, which is above the threshold; however, its low structural transferability limits its weight against the close-analogue low-F evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The highest-transfer analogue (rilzabrutinib, Morgan 0.5152) has direct human absolute bioavailability of only ~5%, far below the 20% threshold, and shares the query's key scaffold. This strong experimental evidence outweighs the mixed physicochemical prior and the less transferable high-F examples from unrelated or distantly related molecules. Therefore, the query is predicted to have low absolute oral bioavailability.",
  "evidence_gaps": [
    "No direct experimental absolute bioavailability measurement for the query molecule itself.",
    "The closest analogue differs in the acrylamide warhead and additional substituents, so the exact impact on first-pass metabolism and absorption is not fully quantified.",
    "No query-specific solubility, permeability, or metabolic stability data are available.",
    "Acalabrutinib demonstrates that some related BTK inhibitors can reach ~25% F, so the scaffold alone is not fully deterministic."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

